import { db, DBClient } from "@/config/db.js";
import AuthService from "@/modules/auth/service.js";
import { UnauthorizedError } from "@/utils/AppError.js";

const VerifyRequest = async (token: string, isAccess = true, client: DBClient = db) => {
    // 1. If no refresh token sent, then throw error
    if (!token) {
        throw new UnauthorizedError(
            "You were logged out successfully.",
            "No token was provided.",
        );
    }

    // 2. Verify if the token was generated by us.
    const decoded = AuthService.VerifyToken(token, isAccess);

    // 3. Find the user based on the Token's userID
    const user = await AuthService.FindUser(decoded.id, client);

    // 4. If no user found, throw error
    if (!user) {
        throw new UnauthorizedError(
            "No account found. Please register a new account.",
        );
    }

    const session = await AuthService.FindSession(user.id, decoded.sessionID, client);

    // 5. If no session found, throw error
    if (!session) {
        throw new UnauthorizedError(
            "You were logged out successfully.",
            "No session was found for this user.",
        );
    }

    return { user, sessionID: decoded.sessionID };
};

export default VerifyRequest;
